                    backgroundColor: isActive ? 'white' : '#FAF6F0',
                    color: isActive ? '#7B5233' : '#64748b',
                    fontSize: '0.85rem',
                    fontWeight: 'bold',
                    borderRadius: '6px 6px 0 0',
